impl Theme {
    /// The tokens for an appearance.
    pub fn get(dark: bool, increase_contrast: bool) -> &'static Theme {
        match (dark, increase_contrast) {
            (true, false) => &DARK,
            (false, false) => &LIGHT,
            (true, true) => &DARK_INCREASE_CONTRAST,
            (false, true) => &LIGHT_INCREASE_CONTRAST,
        }
    }
}

